var last = HIGH;

function setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(3, OUTPUT);
}

function loop() {
  var r = digitalRead(2);
  if (last === HIGH && r === LOW) {
    for (var k = 0; k < 3; k++) {
      digitalWrite(3, HIGH); delay(150);
      digitalWrite(3, LOW); delay(150);
    }
    r = digitalRead(2);
  }
  last = r;
  delay(1);
}
